#pragma once
static std::filesystem::path setupKnown(REFKNOWNFOLDERID id){PWSTR value=nullptr;std::filesystem::path result;if(SUCCEEDED(SHGetKnownFolderPath(id,0,nullptr,&value))){result=value;CoTaskMemFree(value);}return result;}
static std::string setupUtf8(std::wstring const& value){int n=WideCharToMultiByte(CP_UTF8,0,value.data(),int(value.size()),nullptr,0,nullptr,nullptr);std::string result(n,'\0');WideCharToMultiByte(CP_UTF8,0,value.data(),int(value.size()),result.data(),n,nullptr,nullptr);return result;}
static bool validInstallPath(){auto p=setupPath();return (!pathEdit||GetWindowTextLengthW(pathEdit)>0)&&p.find_first_of(L"\"\r\n")==std::wstring::npos&&std::filesystem::path(p).is_absolute();}
#include "setup_path_edit.h"
static void syncPathEdit(){
 if(page==3&&!pathEdit){installDirectory=setupPath();pathEdit=CreateWindowExW(0,L"EDIT",installDirectory.c_str(),WS_CHILD|ES_AUTOHSCROLL|WS_TABSTOP,0,0,0,0,window,reinterpret_cast<HMENU>(101),instance,nullptr);originalPathProc=reinterpret_cast<WNDPROC>(SetWindowLongPtrW(pathEdit,GWLP_WNDPROC,reinterpret_cast<LONG_PTR>(pathProc)));SendMessageW(pathEdit,EM_SETLIMITTEXT,32700,0);}
 if(!pathEdit)return;float scale=GetDpiForWindow(window)/96.f;auto box=settingsGeometry().path;
 if(!pathFont){pathFont=CreateFontW(-int(12*scale),0,0,0,FW_NORMAL,FALSE,FALSE,FALSE,DEFAULT_CHARSET,OUT_DEFAULT_PRECIS,CLIP_DEFAULT_PRECIS,CLEARTYPE_QUALITY,DEFAULT_PITCH,L"Montserrat");SendMessageW(pathEdit,WM_SETFONT,reinterpret_cast<WPARAM>(pathFont),FALSE);}
 RECT r{};GetWindowRect(pathEdit,&r);MapWindowPoints(nullptr,window,reinterpret_cast<POINT*>(&r),2);int x=int((box.left+13)*scale),y=int((box.top+9)*scale),width=int((box.right-box.left-26)*scale),height=int(17*scale);
 if(r.left!=x||r.top!=y||r.right-r.left!=width||r.bottom-r.top!=height)SetWindowPos(pathEdit,nullptr,x,y,width,height,SWP_NOZORDER|SWP_NOACTIVATE|SWP_NOREDRAW);
 bool visible=(GetWindowLongPtrW(pathEdit,GWL_STYLE)&WS_VISIBLE)!=0;if(visible!=(page==3))ShowWindow(pathEdit,page==3?SW_SHOWNA:SW_HIDE);
 InvalidateRect(pathEdit,nullptr,FALSE);
}
static void browseFolder(){ComPtr<IFileOpenDialog> dialog;if(FAILED(CoCreateInstance(CLSID_FileOpenDialog,nullptr,CLSCTX_INPROC_SERVER,IID_PPV_ARGS(&dialog))))return;DWORD flags=0;dialog->GetOptions(&flags);dialog->SetOptions(flags|FOS_PICKFOLDERS|FOS_FORCEFILESYSTEM|FOS_PATHMUSTEXIST);dialog->SetTitle(st(L"Папка установки Torrent",L"Torrent installation folder").c_str());ComPtr<IShellItem> initial;if(SUCCEEDED(SHCreateItemFromParsingName(setupPath().c_str(),nullptr,IID_PPV_ARGS(&initial))))dialog->SetFolder(initial.Get());if(SUCCEEDED(dialog->Show(window))){ComPtr<IShellItem> item;PWSTR path=nullptr;if(SUCCEEDED(dialog->GetResult(&item))&&SUCCEEDED(item->GetDisplayName(SIGDN_FILESYSPATH,&path))){installDirectory=path;CoTaskMemFree(path);if(pathEdit)SetWindowTextW(pathEdit,installDirectory.c_str());InvalidateRect(window,nullptr,FALSE);}}}
// Apply selected setup language/theme only after successful installation; keep download folder/action.
static bool saveInstallTheme(){try{auto root=setupKnown(FOLDERID_LocalAppData)/L"Torrent";std::filesystem::create_directories(root);auto target=root/L"settings.txt";std::string folder=setupUtf8(setupKnown(FOLDERID_Downloads).wstring());int action=0,theme=0,english=0;{std::ifstream input(target,std::ios::binary);std::string old;if(std::getline(input,old)&&!old.empty()){folder=old;input>>action>>theme>>english;}}auto pending=root/L"installer-settings.tmp";{std::ofstream output(pending,std::ios::binary|std::ios::trunc);output<<folder<<'\n'<<action<<' '<<(canvas.dark?1:0)<<' '<<(setupEnglish?1:0);output.flush();if(!output)return false;}return MoveFileExW(pending.c_str(),target.c_str(),MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH)!=0;}catch(...){return false;}}

// Explicitly save Unicode shell links, including their target and icon location.
static bool saveInstallShortcuts(){
 auto executable=std::filesystem::path(setupPath())/L"Torrent.exe";
 auto save=[&](std::filesystem::path const& target){ComPtr<IShellLinkW> link;ComPtr<IPersistFile> file;if(FAILED(CoCreateInstance(CLSID_ShellLink,nullptr,CLSCTX_INPROC_SERVER,IID_PPV_ARGS(&link))))return false;if(FAILED(link->SetPath(executable.c_str()))||FAILED(link->SetWorkingDirectory(setupPath().c_str()))||FAILED(link->SetIconLocation(executable.c_str(),0))||FAILED(link.As(&file)))return false;return SUCCEEDED(file->Save(target.c_str(),TRUE));};
 try{if(desktopShortcut&&!save(setupKnown(FOLDERID_Desktop)/L"Torrent.lnk"))return false;if(startMenuShortcut&&!save(setupKnown(FOLDERID_Programs)/L"Torrent"/L"Torrent.lnk"))return false;return true;}catch(...){return false;}
}